AI Bridge.code:
const ws = await window.aiBridge.connect('ws://localhost:65028');

ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  console.log('Received:', message);
};

ws.onerror = (error) => {
  console.error('WebSocket error:', error);
};

const message = {
  type: 'query',
  data: {
    prompt: 'Your AI prompt here',
    model: 'claude'
  },
  metadata: {
    timestamp: Date.now()
  }
};

window.aiBridge.send(ws, message);

